// A: Numero di buchi (petali del fiore / lobi della figura)
A := int(1,10);   // A e' DISCRETA: lo slider scatta all'intero al rilascio
float numHoles = max(floor(A + 0.5), 1.0); 

// Inizializzazioni
float d_final = 10000.0; 

// --- DEFORMAZIONE TOPOLOGICA RADIALE ---
// F controlla la velocità. anim_scale pulsa fluidamente tra 1.0 e 0.0
float anim_scale = 0.5 + 0.5 * cos(F * ubuf.u_time);

// D funge ora da raggio massimo dell'anello invisibile su cui poggiano i fori
float max_R = max(D, 0.1);
// Il raggio animato fa "sbocciare" e "chiudere" i fori verso il centro
float current_R = max_R * anim_scale;

// Il trucco anti-salto: scaliamo la morbidezza insieme alla distanza dal centro
float current_E = max(E * anim_scale, 0.005); 

for(int k = int(0.0); k < int(20.0); k++) {
    float fk = float(k);

    if(fk < numHoles) { 
        // Calcoliamo l'angolo per questo specifico buco (6.2831853 = 2 * Pi)
        float angle = fk * 6.2831853 / numHoles;

        // Calcoliamo le coordinate X e Y usando le funzioni polari
        float cx = current_R * cos(angle);
        float cy = current_R * sin(angle);

        // Coordinate locali per l'anello corrente
        vec3 p_ring = vec3(p.x - cx, p.y - cy, p.z);

        // Geometria del toro intatta (B = raggio buco, C = spessore tubo)
        float d_ring = length(vec2(length(p_ring.xy) - B, p_ring.z)) - C;

        if(k == int(0.0)) {
            d_final = d_ring; // Primo lobo
        } else {
            // Unione fluida di tutti i lobi disposti a raggiera
            d_final = -smax(-d_final, -d_ring, current_E);
        }
    }
}

return d_final;

